import json,subprocess,tempfile,pathlib

def preview(data,template,required,max_chars=1000):
    if not isinstance(data,dict) or not isinstance(data.get('Alerts'),list):raise ValueError('Alertmanager template Data with Alerts list required')
    if not isinstance(template,str) or not template:raise ValueError('template required')
    if isinstance(max_chars,bool) or not isinstance(max_chars,int) or not 1<=max_chars<=100000:raise ValueError('invalid output bound')
    missing=[]
    for path in required:
        parts=path.split('.')
        if parts[:1]==['CommonLabels']:
            if len(parts)!=2 or not data.get('CommonLabels',{}).get(parts[1]):missing.append(path)
        elif parts[:2]==['Alerts','*'] and len(parts)>=4:
            field='.'.join(parts[2:])
            for index,alert in enumerate(data['Alerts']):
                section,name=field.split('.',1)
                if section not in ('Labels','Annotations') or not alert.get(section,{}).get(name):missing.append(f'Alerts[{index}].{field}')
        else:raise ValueError('unsupported required-field path')
    if missing:return {'ok':False,'missing':missing,'empty':not data['Alerts'],'oversize':False,'rendered':''}
    with tempfile.TemporaryDirectory(prefix='amtool-preview-') as directory:
        path=pathlib.Path(directory)/'data.json';path.write_text(json.dumps(data,ensure_ascii=False),encoding='utf8')
        template_path=pathlib.Path(directory)/'preview.tmpl';template_path.write_text(template,encoding='utf8')
        proc=subprocess.run(['amtool','--no-version-check','template','render','--template.glob='+str(template_path),'--template.text='+template,'--template.data='+str(path)],capture_output=True,text=True,timeout=10,check=False)
    if proc.returncode:raise ValueError('amtool rejected template data or expression: '+proc.stderr[-500:])
    rendered=proc.stdout
    if '<no value>' in rendered:raise ValueError('template referenced missing field')
    return {'ok':True,'missing':[],'empty':not data['Alerts'],'oversize':len(rendered)>max_chars,'rendered':rendered}
```

原题知识说明：
交付脱敏载荷样本、期望渲染结果和结构验证规则。覆盖根数据、CommonLabels不完整、单条Annotations差异、空列表及Unicode，模板内字段作用域必须可验证。使用目标版本支持的离线渲染或隔离测试环境，输出先验证接收格式再做少量授权送达。验收每个模板在全部样本上可解释，不只判定无报错；重要定位字段不可被截断。失败则阻止该模板发布并保留旧版，不能把缺字段统一替换为空掩盖错误，也不向生产API灌入整套测试告警。

